tape( 'the function returns a zero-dimensional ndarray (default)', function test( t ) {
	var arr = tensor0d();
	t.strictEqual( isndarrayLikeWithDataType( arr, 'float64' ), true, 'returns expected value' );
	t.strictEqual( arr.length, 1, 'returns expected value' );
	t.end();
});

tape( 'the function returns a zero-dimensional ndarray (dtype=float64)', function test( t ) {
	var arr = tensor0d( 'float64' );
	t.strictEqual( isndarrayLikeWithDataType( arr, 'float64' ), true, 'returns expected value' );
	t.strictEqual( arr.length, 1, 'returns expected value' );
	t.end();
});

